import React, { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, MenuItem, FormControl, InputLabel, Select } from '@mui/material';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import MultipleImageUpload from '../../components/input/multipleImageUpload';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';
import { axios } from '../../utils/axios'

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};

const AddImages = () => {
  const navigate = useNavigate();
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');
  const [collecDescription, setCollecDescription] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [error, setError] = useState('');
  const [images, setImages] = useState([]);
  const [searchParams, setSearchParams] = useSearchParams();


  const backToGallery = () => {
    const collection = searchParams.get('collection')
    navigate(`/dashboard/editGallery?collection=${collection}`);
  };

  const handleDescriptionChange = (event) => {
    const { value } = event.target;
    if (/^[A-Za-z\s]*$/.test(value)) { // Allow only letters and spaces
      setCollecDescription(value);
      if (value.length < 2) {
        setError('Description is too short');
      } else {
        setError('');
      }
    }
  };

  const handleCategoryChange = (event) => {
    setSelectedCategory(event.target.value);
  };

  const handleImageChange = (uploadedImages) => {
    setImages(uploadedImages);
  };

  const addCollections = async () => {
    // Validate category selection
    // if (!selectedCategory) {
    //   GenerateToastConfig('Please select a category');
    //   return;
    // }
    
    // Validate if images are selected
    if (images.length === 0) {
      GenerateToastConfig('Please upload at least one image');
      return;
    }

    // Proceed with the API call
    try {
      const formData = new FormData();
      formData.append('collection', selectedCategory);
      formData.append('description', collecDescription);
      images.forEach((image) => formData.append('images', image)); // Append all images
      const collectionID = searchParams.get('collection')
      const response = await axios.post(`module/gallery/images?collectionName=${collectionID} `, formData)
      if(response.status === 201) {
        GenerateToastConfig(response?.data?.message, 'success');
        backToGallery();
      }

    } catch (error) {
      GenerateToastConfig(error.response?.data?.message || 'Error adding collection');
    }
  };

  return (
    <>
      <Helmet>
        <title>{`Add Collection`}</title>
      </Helmet>
      <Card>
        <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer'
                }}
                onClick={backToGallery}
              >
                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
              </Box>
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                    {i18?.ACCOUNTSTITLE?.ADD_IMAGES || "Add Images"}
              </Typography>
            </Box>
          </Grid>
        </Grid>

        <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px" }} />

        <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          {/* Category Field */}
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
            {/* <InputLabel sx={{ color: "#2B3343" }} id="category-select-label">
              {i18?.ACCOUNTSTITLE?.COLLECTION_NAME || "Collection Name"}
            </InputLabel> */}
            {/* <FormControl sx={{ marginTop: '10px' }} fullWidth>
              <Select
                labelId="category-select-label"
                id="category-select"
                sx={{
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                value={selectedCategory}
                onChange={handleCategoryChange}
                MenuProps={MenuProps}
                required
              >
                <MenuItem value="listings">Listingssss</MenuItem>
                <MenuItem value="profiles">Profiles</MenuItem>
                <MenuItem value="amenities">Amenities</MenuItem>
                <MenuItem value="icons">Icons</MenuItem>
              </Select>
            </FormControl> */}
                      {/* <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}> */}
            {/* <InputField
                value={selectedCategory}
              name="Collection Name"
              label={i18?.ACCOUNTSTITLE?.DESCRIPTION || "Collection name"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                },
              }}
              onChange={handleCategoryChange}
              type="text"
              required
            />
            {error && <Typography color="error">{error}</Typography>} */}
          {/* </Grid> */}
          </Grid>
          {/* Description Field */}
          <Grid item xs={12} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
            <InputField
              value={collecDescription}
              name="description"
              label={i18?.ACCOUNTSTITLE?.DESCRIPTION || "Description"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                },
              }}
              onChange={handleDescriptionChange}
              type="text"
              required
            />
            {error && <Typography color="error">{error}</Typography>}
          </Grid>
          {/* Image Upload Field */}
          <Grid item xs={12} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
            {/* <InputLabel sx={{ color: "#2B3343" }} id="image-upload-label">
              {i18?.ACCOUNTSTITLE?.SELECT_IMAGES || 'Select Images'}
            </InputLabel> */}
            <MultipleImageUpload
              name="images"
              label={i18?.ACCOUNTSTITLE?.IMAGES || "Upload Images"}
              multiple
              accept="image/*"
              onChange={handleImageChange}
              value={images}
            />
          </Grid>
        </Grid>

        <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px", width: "100%"}}/>
        <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Button
            sx={{
              padding: "10px 58px 10px 58px"
            }}
            disabled={!collecDescription || images.length === 0}
            variant="contained"
            onClick={addCollections}
          >
            {i18?.ACCOUNTSTITLE?.ADD || "Add"}
          </Button>
        </Grid>
      </Card>
    </>
  );
};

export default AddImages;
